package kr.closeforyou.accessibility

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.security.MessageDigest
import java.util.Properties
import kotlinx.collections.immutable.persistentSetOf
import kr.closeforyou.core.model.NodeAction
import kr.closeforyou.core.model.NodeSnapshot
import kr.closeforyou.core.model.ScreenBounds
import org.junit.Assert.*
import org.junit.Test

/** Python-authored static byte streams/hashes. No expectations are generated by this codec. */
class SnapshotFingerprintCodecTest {
    private val golden = Properties().apply {
        requireNotNull(SnapshotFingerprintCodecTest::class.java.getResourceAsStream("/snapshot_fingerprint_v1_golden.properties")) {
            "SYNTHETIC_GOLDENS_MISSING"
        }.use(::load)
    }
    private val salt = decode(golden.getProperty("salt"))
    private val codec = SnapshotFingerprintCodec(salt)
    private val tree = listOf(
        SnapshotFingerprintNode(NodeSnapshot("0", null, "android.widget.FrameLayout", null, "", false, true,
            ScreenBounds(0, 0, 1080, 1920)), 2),
        SnapshotFingerprintNode(NodeSnapshot("0/0", "synthetic:id/공지", "android.widget.TextView", "합성 점검 공지🙂",
            null, false, true, ScreenBounds(24, 60, 1056, 600)), 0),
        SnapshotFingerprintNode(NodeSnapshot("0/1", "", null, "닫기", "합성 설명\n확인", true, false,
            ScreenBounds(-7, 640, 1001, 880), persistentSetOf(NodeAction.CLICK, NodeAction.DISMISS)), 0),
    )

    @Test fun staticStreamsRehashToPythonGoldenBytesWithoutUsingCodec() {
        val keys = golden.stringPropertyNames().filter { it.endsWith(".stream") }
        assertEquals(22, keys.size)
        for (key in keys) {
            val hash = MessageDigest.getInstance("SHA-256")
            hash.update(salt)
            hash.update(decode(golden.getProperty(key)))
            assertArrayEquals(decode(golden.getProperty(key.removeSuffix(".stream") + ".sha256")), hash.digest())
        }
    }

    @Test fun structureMatchesIndependentFullTreeGoldenByteForByte() =
        matches("structure.tree", codec.structure(tree))

    @Test fun contentMatchesIndependentFullTreeGoldenByteForByte() =
        matches("content.tree", codec.content(tree))

    @Test fun eachOutlineMatchesItsIndependentGolden() {
        tree.forEachIndexed { index, node -> matches("outline.node$index", codec.outline(node.snapshot)) }
    }

    @Test fun applicationMatchesIndependentGolden() =
        matches("application", codec.application("kr.closeforyou.synthetic"))

    @Test fun emptyTraversalsHaveOnlySaltAndNoInventedDomainTag() {
        matches("structure.empty", codec.structure(emptyList()))
        matches("content.empty", codec.content(emptyList()))
        assertArrayEquals(codec.structure(emptyList()).bytes(), codec.content(emptyList()).bytes())
    }

    @Test fun nullAndEmptyHaveDistinctGoldenDigests() {
        val nullEmpty = codec.outline(tree[0].snapshot.copy(viewId = null, className = ""))
        val emptyNull = codec.outline(tree[0].snapshot.copy(viewId = "", className = null))
        matches("outline.null_empty", nullEmpty)
        matches("outline.empty_null", emptyNull)
        differs(nullEmpty, emptyNull)
        assertArrayEquals(decode("0000000130ffffffff00000000"), stream("outline.null_empty"))
        assertArrayEquals(decode("000000013000000000ffffffff"), stream("outline.empty_null"))
    }

    @Test fun koreanAndSurrogatePairUseUtf8ByteLengths() {
        matches("outline.utf8", codec.outline(tree[1].snapshot.copy(viewId = "한글", className = "🙂")))
        assertArrayEquals(decode("00000003302f3000000006ed959ceab88000000004f09f9982"), stream("outline.utf8"))
    }

    @Test fun lengthOver255UsesFourByteBigEndianPrefix() {
        matches("outline.long_utf8", codec.outline(tree[0].snapshot.copy(viewId = "가".repeat(86), className = null)))
        assertArrayEquals(byteArrayOf(0, 0, 1, 2), stream("outline.long_utf8").copyOfRange(5, 9))
    }

    @Test fun unpairedHighSurrogateMatchesJvmReplacementEncoding() = matches("outline.unpaired_high",
        codec.outline(tree[0].snapshot.copy(viewId = "\uD800", className = null)))

    @Test fun unpairedLowSurrogateMatchesJvmReplacementEncoding() = matches("outline.unpaired_low",
        codec.outline(tree[0].snapshot.copy(viewId = "\uDC00", className = null)))

    @Test fun unicodeIsNeverNormalizedBeforeHashing() {
        val decomposed = codec.outline(tree[1].snapshot.copy(viewId = "한글", className = "🙂"))
        matches("outline.decomposed", decomposed)
        differs(decomposed, codec.outline(tree[1].snapshot.copy(viewId = "한글", className = "🙂")))
    }

    @Test fun swappedFieldOrderMatchesDifferentGolden() {
        val swapped = codec.outline(tree[1].snapshot.copy(viewId = "🙂", className = "한글"))
        matches("outline.swapped_fields", swapped)
        differs(swapped, codec.outline(tree[1].snapshot.copy(viewId = "한글", className = "🙂")))
    }

    @Test fun reversedPreorderChangesStructureToIndependentGolden() {
        matches("structure.reordered", codec.structure(tree.reversed()))
        differs(codec.structure(tree), codec.structure(tree.reversed()))
    }

    @Test fun reversedPreorderChangesContentToIndependentGolden() {
        matches("content.reordered", codec.content(tree.reversed()))
        differs(codec.content(tree), codec.content(tree.reversed()))
    }

    @Test fun noActionsSerializeAsEmptyField() = matches("structure.actions.none", codec.structure(listOf(actionNode())))
    @Test fun clickActionHasExactEnumSpelling() = matches("structure.actions.click",
        codec.structure(listOf(actionNode(NodeAction.CLICK))))
    @Test fun dismissActionHasExactEnumSpelling() = matches("structure.actions.dismiss",
        codec.structure(listOf(actionNode(NodeAction.DISMISS))))
    @Test fun bothActionsUseCommaWithoutSpaces() = matches("structure.actions.both",
        codec.structure(listOf(actionNode(NodeAction.CLICK, NodeAction.DISMISS))))

    @Test fun reversedIncomingActionSetUsesCollectorOrderWithoutMutatingInput() {
        val record = actionNode(NodeAction.DISMISS, NodeAction.CLICK)
        matches("structure.actions.both", codec.structure(listOf(record)))
        assertEquals(listOf(NodeAction.DISMISS, NodeAction.CLICK), record.snapshot.actions.toList())
    }

    @Test fun eachExistingStructureFieldContributes() {
        val original = tree[0]
        val n = original.snapshot
        val variants = listOf(n.copy(path = "0/9"), n.copy(viewId = "id"), n.copy(className = "Other"),
            n.copy(bounds = n.bounds.copy(left = -1)), n.copy(bounds = n.bounds.copy(top = -1)),
            n.copy(bounds = n.bounds.copy(right = 1081)), n.copy(bounds = n.bounds.copy(bottom = 1921)),
            n.copy(clickable = true), n.copy(enabled = false), n.copy(actions = persistentSetOf(NodeAction.CLICK)))
        variants.forEach { differs(codec.structure(listOf(original)), codec.structure(listOf(original.copy(snapshot = it)))) }
        differs(codec.structure(listOf(original)), codec.structure(listOf(original.copy(childCount = 3))))
    }

    @Test fun contentContainsExactlyPathTextAndDescription() {
        val original = tree[1]
        listOf(original.snapshot.copy(path = "0/9"), original.snapshot.copy(text = "다른 합성 공지"),
            original.snapshot.copy(contentDescription = "")).forEach {
            differs(codec.content(listOf(original)), codec.content(listOf(original.copy(snapshot = it))))
        }
    }

    @Test fun structureDoesNotInventBodyOrDescriptionFields() {
        val modified = tree.map { it.copy(snapshot = it.snapshot.copy(text = "다른 합성 본문", contentDescription = "다른 설명")) }
        assertArrayEquals(codec.structure(tree).bytes(), codec.structure(modified).bytes())
        differs(codec.content(tree), codec.content(modified))
    }

    @Test fun contentDoesNotInventBoundsActionsOrChildCountFields() {
        val modified = tree.map { it.copy(childCount = 9, snapshot = it.snapshot.copy(bounds = ScreenBounds(1, 2, 3, 4),
            actions = persistentSetOf(NodeAction.DISMISS), clickable = !it.snapshot.clickable, enabled = !it.snapshot.enabled)) }
        assertArrayEquals(codec.content(tree).bytes(), codec.content(modified).bytes())
        differs(codec.structure(tree), codec.structure(modified))
    }

    @Test fun outlineContainsOnlyPathViewIdAndClassName() {
        val n = tree[1].snapshot
        val changed = n.copy(text = "다른 본문", contentDescription = "다른 설명", bounds = ScreenBounds(1, 2, 3, 4),
            clickable = true, enabled = false, actions = persistentSetOf(NodeAction.DISMISS))
        assertArrayEquals(codec.outline(n).bytes(), codec.outline(changed).bytes())
        listOf(n.copy(path = "0/9"), n.copy(viewId = "다른 ID"), n.copy(className = null)).forEach {
            differs(codec.outline(n), codec.outline(it))
        }
    }

    @Test fun differentPackageChangesApplicationDigest() =
        differs(codec.application("kr.closeforyou.synthetic"), codec.application("kr.closeforyou.synthetic.other"))

    @Test fun sameFixedSaltAndInputsReproduceAllFourKinds() {
        val other = SnapshotFingerprintCodec(salt.copyOf())
        assertArrayEquals(codec.structure(tree).bytes(), other.structure(tree).bytes())
        assertArrayEquals(codec.content(tree).bytes(), other.content(tree).bytes())
        assertArrayEquals(codec.outline(tree[0].snapshot).bytes(), other.outline(tree[0].snapshot).bytes())
        assertArrayEquals(codec.application("synthetic").bytes(), other.application("synthetic").bytes())
    }

    @Test fun saltChangeAffectsAllFourKinds() {
        val other = SnapshotFingerprintCodec(salt.copyOf().also { it[31] = 0 })
        differs(codec.structure(tree), other.structure(tree))
        differs(codec.content(tree), other.content(tree))
        differs(codec.outline(tree[0].snapshot), other.outline(tree[0].snapshot))
        differs(codec.application("synthetic"), other.application("synthetic"))
    }

    @Test fun constructorDefensivelyCopiesCollectorsSalt() {
        val supplied = salt.copyOf()
        val isolated = SnapshotFingerprintCodec(supplied)
        supplied.fill(99)
        matches("structure.tree", isolated.structure(tree))
    }

    @Test fun returnedDigestBytesCannotMutateDigest() {
        val digest = codec.content(tree)
        digest.bytes().fill(99)
        matches("content.tree", digest)
    }

    @Test fun interleavedCallsDoNotAccumulateHashState() {
        repeat(3) {
            matches("structure.tree", codec.structure(tree))
            matches("application", codec.application("kr.closeforyou.synthetic"))
            matches("content.tree", codec.content(tree))
        }
    }

    @Test fun v1HexPreservesLeadingZeroesAndLowercase() {
        val bytes = ByteArray(32) { it.toByte() }
        assertEquals("000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f",
            SnapshotFingerprintDigest(bytes).hex())
    }

    @Test fun invalidSaltHasOnlyFixedExceptionCode() {
        for (size in listOf(0, 31, 33)) {
            try {
                SnapshotFingerprintCodec(ByteArray(size) { 99 })
                fail("INVALID_SALT_ACCEPTED")
            } catch (failure: IllegalArgumentException) {
                assertEquals("FINGERPRINT_SALT_SIZE", failure.message)
            }
        }
    }

    @Test fun wrappersAreRedactedAndCodecDoesNotWriteDiagnostics() {
        val previousOut = System.out
        val previousErr = System.err
        val output = ByteArrayOutputStream()
        val capture = PrintStream(output)
        try {
            System.setOut(capture)
            System.setErr(capture)
            val digests = listOf(codec.structure(tree), codec.content(tree), codec.outline(tree[1].snapshot),
                codec.application("kr.closeforyou.synthetic"))
            assertEquals("SnapshotFingerprintCodec(V1, redacted)", codec.toString())
            assertEquals("SnapshotFingerprintNode(redacted)", tree[1].toString())
            digests.forEach { assertEquals("SnapshotFingerprintDigest(redacted)", it.toString()) }
            assertEquals("", output.toString())
        } finally {
            System.setOut(previousOut)
            System.setErr(previousErr)
            capture.close()
        }
    }

    private fun actionNode(vararg actions: NodeAction) = tree[0].copy(childCount = 0,
        snapshot = tree[0].snapshot.copy(actions = persistentSetOf(*actions)))
    private fun matches(key: String, actual: SnapshotFingerprintDigest) {
        val expected = golden.getProperty("$key.sha256")
        assertArrayEquals(decode(expected), actual.bytes())
        assertEquals(expected, actual.hex())
        assertEquals(32, actual.bytes().size)
    }
    private fun differs(a: SnapshotFingerprintDigest, b: SnapshotFingerprintDigest) =
        assertFalse(a.bytes().contentEquals(b.bytes()))
    private fun stream(key: String) = decode(golden.getProperty("$key.stream"))
    private fun decode(hex: String) = ByteArray(hex.length / 2) { hex.substring(it * 2, it * 2 + 2).toInt(16).toByte() }
}
